import {createPrediction,predictionAnswer,predictionHint,predictionScore} from './prediction-model.mjs';
export function createPredictionUI({experiment,seek,resume,refresh,ready}){
 const root=document.querySelector('#guided'),q=s=>root.querySelector(s);let game=null;
 root.innerHTML='<div class="actions"><h2>Predice el siguiente scan</h2><button id="guideStart">Iniciar modo guiado</button><button id="guideExit" hidden>Salir del modo guiado</button></div><p>Marcha está solicitada en ambos bancos desde el inicio. Pausamos 20 ms antes de cada cambio de sensores, salidas o contactos supervisados (RUN válido, P01 y T1–T4.Q). Elige una señal que cambiará en el banco indicado: solo una de las opciones es correcta. Puede haber otros cambios simultáneos.</p><p>Por pregunta: 100 puntos, −20 por error y −10 por pista (máximo dos). Consultar solución vale 0. La nota es la media de las preguntas resueltas, sin premio por rapidez. Progreso de esta sesión.</p><div id="guideBody" hidden><p id="guideProgress"></p><h3 id="guideQuestion"></h3><div id="guideChoices" class="actions"></div><div class="actions"><button id="guideHint">Pista</button><button id="guideReveal">Ver solución</button><button id="guideNext" hidden>Continuar hasta el próximo cambio</button></div><p id="guideHintText"></p><p id="guideFeedback" role="status"></p><ul id="guideChanges"></ul></div>';
 function render(){q('#guideStart').disabled=!ready();q('#guideStart').hidden=!!game;q('#guideExit').hidden=!game;q('#guideBody').hidden=!game;if(!game)return;const e=game.events[game.at],done=game.phase==='complete',answer=game.phase==='answer';q('#guideProgress').textContent='Resueltas '+game.results.length+' / '+game.events.length+' · Nota '+predictionScore(game)+'/100 · Errores esta pregunta: '+game.attempts+' · Pistas: '+game.hints;
 q('#guideQuestion').textContent=done?'Recorrido completado. Revisa las diferencias en modo libre.':game.phase==='travel'?'Observa cómo avanza el proceso…':'Banco '+(e.bank==='fault'?'con fallo':'normal')+' · ¿Qué cambiará en el scan de '+(e.index*.02).toFixed(2)+' s?';
 const key=game.at+':'+game.phase;if(q('#guideChoices').dataset.key!==key){q('#guideChoices').dataset.key=key;if(game.phase==='question'){q('#guideQuestion').tabIndex=-1;q('#guideQuestion').focus({preventScroll:true});root.scrollIntoView({block:'center'});}q('#guideChoices').replaceChildren();if(game.phase==='question')for(const option of e.options){const b=document.createElement('button');b.textContent=option.label;b.onclick=()=>answerWith(option.id);q('#guideChoices').append(b);}}
 q('#guideHint').hidden=q('#guideReveal').hidden=game.phase!=='question';q('#guideHint').disabled=game.hints>=2;q('#guideNext').hidden=!answer;
 q('#guideHintText').textContent=game.phase==='question'&&game.hints?(game.hints===1?'Pista 1: tipo de señal: '+e.answer.type+'. Compara posición, entradas y etapa actual.':'Pista 2: la señal pasará de '+e.answer.from+' a '+e.answer.to+'. '+(e.answer.type==='salida'?'Revisa el permiso RUN y la etapa que escribe las bobinas.':e.answer.type==='sensor'?'Observa extremos del pistón y presión; una conexión intermitente puede cambiar sin movimiento.':'Revisa las condiciones lógicas y el tiempo acumulado de los TON.')):'';
 q('#guideFeedback').textContent=game.feedback;q('#guideChanges').replaceChildren();if(answer)for(const c of e.changes){const li=document.createElement('li');li.textContent=(c.bank==='fault'?'Con fallo':'Normal')+' · '+c.label+': '+c.from+' → '+c.to;q('#guideChanges').append(li);}if(answer){const li=document.createElement('li');li.textContent='La imagen ya muestra el scan resuelto. Las entradas se leen antes de evaluar el ladder; las salidas se escriben al final. El movimiento responde en el scan siguiente.';q('#guideChanges').append(li);}}
 function answerWith(id,reveal=false){if(!game)return;if(predictionAnswer(game,id,reveal))seek(game.events[game.at].index);else render();}
 q('#guideStart').onclick=()=>{game=createPrediction(experiment());seek(game.events[0].index-1);};
 q('#guideExit').onclick=()=>{game=null;refresh();};q('#guideHint').onclick=()=>{predictionHint(game);render();};q('#guideReveal').onclick=()=>answerWith(null,true);
 q('#guideNext').onclick=()=>{game.at++;game.attempts=game.hints=0;game.feedback='';if(game.at>=game.events.length){game.phase='complete';refresh();return;}game.phase='travel';resume();};
 return {active:()=>!!game,render,limit(next){if(!game||game.phase!=='travel')return next;const boundary=game.events[game.at].index-1;if(next>=boundary){game.phase='question';return boundary;}return next;},waiting:()=>!!game&&game.phase!=='travel',state:()=>game};
}
